async getAllIDs() {
  const ids = await super.getAllIDs();
  for (const s of MailServices.outgoingServer.servers) {
    ids[s.UID] = true;
  }
  for (const s of MailServices.accounts.allServers) {
    if (
      ["imap", "pop3"].includes(s.type) &&
      authMethodForRecord(s.authMethod)
    ) {
      ids[s.UID] = true;
    }
  }
  return ids;
